    20	    public void validate(CheckoutRequestDto request, BigDecimal productsSubtotal) {
    21	        if (request.getCoupon() == null || request.getCoupon().isEmpty()) {
    22	            return;
    23	        }
    24	
    25	        CouponCode coupon = CouponCode.valueOf(request.getCoupon());
    26	
    27	        switch (coupon) {
    28	            case WELCOME10:
    29	                validateWelcome10(request);
    30	                break;
    31	            case MINUS50:
    32	                validateMinus50(productsSubtotal);
    33	                break;
    34	            case FREESHIPPING:
    35	                validateFreeShipping(request);
    36	                break;
    37	            case BUY3PAY2:
    38	                break;
    39	        }
    40	    }
    41	
    42	    private void validateWelcome10(CheckoutRequestDto request) {
    43	        String cpf = request.getCustomer().getCpf();
    44	        List<Order> customerOrders = orderRepository.findAll();
    45	        boolean hasPaidOrder = customerOrders.stream()
    46	                .anyMatch(o -> o.getCustomerCpf().equals(cpf) &&
    47	                        (o.getStatus().name().equals("PAID") ||
    48	                         o.getStatus().name().equals("SHIPPED") ||
    49	                         o.getStatus().name().equals("DELIVERED")));
    50	
    51	        if (hasPaidOrder) {
    52	            throw new CouponNotApplicableException();
    53	        }
    54	    }
    55	
    56	    private void validateMinus50(BigDecimal productsSubtotal) {
    57	        if (productsSubtotal.compareTo(new BigDecimal("300")) < 0) {
    58	            throw new CouponNotApplicableException();
    59	        }
    60	    }
    61	
    62	    private void validateFreeShipping(CheckoutRequestDto request) {
    63	        ShippingMethod method = ShippingMethod.valueOf(request.getShippingMethod());
    64	        if (method == ShippingMethod.STORE_PICKUP) {
    65	            throw new CouponNotApplicableException();
    66	        }
    67	    }
    68	}
