    87	    private BigDecimal calculateCouponDiscount(CheckoutRequestDto request, BigDecimal productsSubtotal, BigDecimal shippingCost, ShippingMethod shippingMethod) {
    88	        if (request.getCoupon() == null || request.getCoupon().isEmpty()) {
    89	            return BigDecimal.ZERO;
    90	        }
    91	
    92	        CouponCode coupon = CouponCode.valueOf(request.getCoupon());
    93	        BigDecimal discount = BigDecimal.ZERO;
    94	
    95	        switch (coupon) {
    96	            case WELCOME10:
    97	                discount = productsSubtotal.multiply(new BigDecimal("0.10"));
    98	                break;
    99	            case MINUS50:
   100	                if (productsSubtotal.compareTo(new BigDecimal("300")) >= 0) {
   101	                    discount = new BigDecimal("50");
   102	                }
   103	                break;
   104	            case FREESHIPPING:
   105	                if (shippingMethod != ShippingMethod.STORE_PICKUP) {
   106	                    discount = shippingCost;
   107	                }
   108	                break;
   109	            case BUY3PAY2:
   110	                discount = calculateBuy3Pay2Discount(request, productsSubtotal);
   111	                break;
   112	        }
   113	
   114	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"));
   115	        if (discount.compareTo(maxDiscount) > 0) {
   116	            discount = maxDiscount;
   117	        }
   118	
   119	        return discount;
   120	    }
   121	
   122	    private BigDecimal calculateBuy3Pay2Discount(CheckoutRequestDto request, BigDecimal productsSubtotal) {
   123	        BigDecimal discount = BigDecimal.ZERO;
   124	
   125	        Map<String, Integer> skuQuantities = new HashMap<>();
   126	        for (var item : request.getItems()) {
   127	            skuQuantities.put(item.getSku(), item.getQuantity());
   128	        }
   129	
   130	        for (var entry : skuQuantities.entrySet()) {
   131	            int quantity = entry.getValue();
   132	            int freeUnits = quantity / 3;
   133	            if (freeUnits > 0) {
   134	                Product product = productService.getProduct(entry.getKey());
   135	                discount = discount.add(product.getPrice().multiply(new BigDecimal(freeUnits)));
   136	            }
   137	        }
   138	
   139	        return discount;
   140	    }
