   229	    private BigDecimal calculatePaymentAdjustment(CheckoutRequestDto request, BigDecimal subtotal) {
   230	        PaymentMethod method = PaymentMethod.valueOf(request.getPaymentMethod());
   231	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
   232	
   233	        switch (method) {
