   297	    private Boolean shouldGift(BigDecimal productsSubtotal, ClubTier tier) {
   298	        if (tier == ClubTier.GOLD && productsSubtotal.compareTo(new BigDecimal("500")) > 0) {
   299	            return true;
   300	        }
   301	        return false;
   302	    }
