    30	    private void validateItems(CheckoutRequestDto request) {
    31	        if (request.getItems() == null || request.getItems().isEmpty()) {
    32	            throw new InvalidOrderException();
    33	        }
    34	
    35	        Set<String> seenSkus = new HashSet<>();
    36	        for (var item : request.getItems()) {
    37	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
    38	                throw new InvalidOrderException();
    39	            }
    40	            if (!seenSkus.add(item.getSku())) {
    41	                throw new InvalidOrderException();
    42	            }
    43	        }
    44	
    45	        for (var item : request.getItems()) {
    46	            Product product = productService.getProduct(item.getSku());
    47	            if (product == null) {
    48	                throw new UnknownProductException();
    49	            }
    50	            if (product.isDiscontinued()) {
    51	                throw new ProductDiscontinuedException();
    52	            }
    53	            if (product.getStock() < item.getQuantity()) {
    54	                throw new InsufficientStockException();
    55	            }
    56	        }
    57	    }
    58	
    59	    private void validateCustomer(CheckoutRequestDto request) {
    60	        if (request.getCustomer() == null ||
    61	                request.getCustomer().getCpf() == null ||
    62	                request.getCustomer().getEmail() == null) {
    63	            throw new InvalidOrderException();
    64	        }
    65	    }
    66	
    67	    private void validateRegion(CheckoutRequestDto request) {
    68	        try {
    69	            Region.valueOf(request.getRegion());
    70	        } catch (IllegalArgumentException e) {
    71	            throw new InvalidRegionException();
    72	        }
    73	    }
    74	
    75	    private void validateZipCode(CheckoutRequestDto request) {
    76	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
    77	            throw new InvalidZipCodeException();
    78	        }
    79	    }
    80	
    81	    private void validateShippingMethod(CheckoutRequestDto request) {
    82	        ShippingMethod method;
    83	        try {
    84	            method = ShippingMethod.valueOf(request.getShippingMethod());
    85	        } catch (IllegalArgumentException e) {
    86	            throw new InvalidShippingMethodException();
    87	        }
    88	
    89	        if (method == ShippingMethod.COURIER) {
    90	            BigDecimal totalWeight = calculateTotalWeight(request);
    91	            if (totalWeight.compareTo(new BigDecimal("5")) > 0) {
    92	                throw new ShippingMethodUnavailableException();
    93	            }
    94	        }
    95	    }
    96	
    97	    private void validateClubTier(CheckoutRequestDto request) {
    98	        try {
    99	            ClubTier.valueOf(request.getClubTier());
   100	        } catch (IllegalArgumentException e) {
   101	            throw new InvalidClubTierException();
