   106	        if (request.getCoupon() != null && !request.getCoupon().isEmpty()) {
   107	            try {
   108	                CouponCode.valueOf(request.getCoupon());
   109	            } catch (IllegalArgumentException e) {
   110	                throw new InvalidCouponException();
   111	            }
   112	        }
   113	    }
   114	
   115	    private void validatePaymentMethod(CheckoutRequestDto request) {
   116	        PaymentMethod method;
   117	        try {
   118	            method = PaymentMethod.valueOf(request.getPaymentMethod());
   119	        } catch (IllegalArgumentException e) {
   120	            throw new InvalidPaymentMethodException();
   121	        }
   122	
   123	        Integer installments = request.getInstallments() != null ? request.getInstallments() : 1;
   124	
   125	        if (method == PaymentMethod.PIX || method == PaymentMethod.BANK_SLIP) {
   126	            if (installments != 1) {
   127	                throw new InvalidInstallmentsException();
   128	            }
   129	        } else if (method == PaymentMethod.CREDIT_CARD) {
   130	            if (installments < 1 || installments > 12) {
   131	                throw new InvalidInstallmentsException();
   132	            }
   133	        }
   134	    }
